import json
from collections import deque
from itertools import product
from tfl.automata import DFA
from tfl.words import iter_words

alphabet = frozenset('ab')
states = (0, 1)
words = tuple(iter_words('ab', 3))
automata = []
for targets in product(states, repeat=4):
    delta = {}
    k = 0
    for q in states:
        for ch in sorted(alphabet):
            delta[(q, ch)] = targets[k]
            k += 1
    for mask in range(4):
        finals = frozenset(q for q in states if mask & (1 << q))
        automata.append(DFA(alphabet, 0, finals, delta))

pairs_checked = 0
state_obligations = 0
for A1 in automata:
    for A2 in automata:
        pair_states = set(product(states, states))
        back = {pair: set() for pair in pair_states}
        for q1, q2 in pair_states:
            for ch in alphabet:
                nxt = (A1.delta[(q1, ch)], A2.delta[(q2, ch)])
                back[nxt].add((q1, q2))
        reachable_to_joint_final = {
            pair for pair in pair_states
            if pair[0] in A1.finals and pair[1] in A2.finals
        }
        queue = deque(reachable_to_joint_final)
        while queue:
            cur = queue.popleft()
            for prev in back[cur]:
                if prev not in reachable_to_joint_final:
                    reachable_to_joint_final.add(prev)
                    queue.append(prev)
        G = {q for q in states if (q, A2.start) in reachable_to_joint_final}
        for q in states:
            direct = any(
                A1.run(v) in A1.finals and A2.accepts(v)
                for v in words
            ) if q == A1.start else any(
                (lambda end: end in A1.finals)(
                    __import__('functools').reduce(
                        lambda st, ch: A1.delta[(st, ch)], v, q
                    )
                ) and A2.accepts(v)
                for v in words
            )
            assert (q in G) == direct
            state_obligations += 1
        pairs_checked += 1
print(json.dumps({
    'alphabet': ['a', 'b'],
    'states_per_dfa': 2,
    'complete_dfas_checked': len(automata),
    'dfa_pairs_checked': pairs_checked,
    'state_obligations_checked': state_obligations,
    'suffix_witness_bound': 3,
    'mismatches': 0
}, sort_keys=True))
